// Type definitions previously generated by `ts-rs` are inlined below
// (M2.5 codegen retirement). When changing any of these, mirror the
// edit in the corresponding Rust struct/enum in
// `backend/crates/golish-*` to keep both sides in lockstep.

/**
 * AI provider selection.
 */
export type AiProvider =
  | "vertex_ai"
  | "vertex_gemini"
  | "openrouter"
  | "anthropic"
  | "openai"
  | "ollama"
  | "gemini"
  | "groq"
  | "xai"
  | "zai_sdk"
  | "nvidia"
  | "deepseek"
  | "xiaomi";

/**
 * Reasoning effort level for models that support it (e.g., OpenAI o-series, GPT-5).
 */
export type ReasoningEffort = "low" | "medium" | "high" | "extra_high";

/**
 * Risk level for a tool operation.
 */
export type RiskLevel = "low" | "medium" | "high" | "critical";

export interface ProviderRequestStatsSnapshot {
  requests: bigint;
  last_sent_at: bigint | null;
  last_received_at: bigint | null;
}

export interface ApiRequestStatsSnapshot {
  providers: { [key: string]: ProviderRequestStatsSnapshot };
}

export interface ProjectSettings {
  provider: AiProvider | null;
  model: string | null;
  agent_mode: AgentMode | null;
}

export interface AiConfig {
  workspace: string;
  provider: AiProvider;
  model: string;
  apiKey: string;
}

/**
 * User-supplied per-(provider, model) override forwarded to the backend.
 *
 * Mirror of `backend/crates/golish-settings/src/schema/ai.rs::ModelOverride`
 * and the frontend's {@link ModelOverride} in `lib/settings/types.ts`.
 *
 * The backend uses this to:
 * - Toggle `quirks.reasoning_handling` between `Standard` and `AlwaysContent`
 * - Inject `chat_template_kwargs.enable_thinking=false` on the outgoing request
 * - Apply `reasoning.effort` / `max_tokens` overrides where supported
 */
export interface ProviderModelOverride {
  thinking?: boolean;
  reasoning_effort?: string;
  max_tokens?: number;
  context_window?: number;
  stream_debug?: boolean;
}

interface ProviderConfigBase {
  /** Optional per-model override applied alongside provider defaults. */
  model_override?: ProviderModelOverride;
}

