export type AgentMode = "default" | "auto-approve" | "planning";

/**
 * User's decision on an approval request.
 */
export interface ApprovalDecision {
  request_id: string;
  approved: boolean;
  reason: string | null;
  remember: boolean;
  always_allow: boolean;
}

/**
 * Role of a message in the conversation (simplified for Golish).
 */
export type SessionMessageRole = "user" | "assistant" | "system" | "tool";

/**
 * A simplified message format for Golish sessions.
 */
export interface SessionMessage {
  role: SessionMessageRole;
  content: string;
  tool_call_id?: string | null;
  tool_name?: string | null;
  tokens_used?: number | null;
}

/**
 * Golish session snapshot containing conversation data.
 */
export interface SessionSnapshot {
  workspace_label: string;
  workspace_path: string;
  model: string;
  provider: string;
  started_at: string;
  ended_at: string;
  total_messages: number;
  distinct_tools: string[];
  transcript: string[];
  messages: SessionMessage[];
  sidecar_session_id: string | null;
  total_tokens?: bigint | null;
  agent_mode?: string | null;
}

/**
 * Session listing information for display.
 */
export interface SessionListingInfo {
  identifier: string;
  path: string;
  workspace_label: string;
  workspace_path: string;
  model: string;
  provider: string;
  started_at: string;
  ended_at: string;
  total_messages: number;
  distinct_tools: string[];
  first_prompt_preview: string | null;
  first_reply_preview: string | null;
  status: string | null;
  title: string | null;
}

/**
 * Configuration for tool approval behavior.
 */
export interface ToolApprovalConfig {
  always_allow: string[];
  always_require_approval: string[];
  pattern_learning_enabled: boolean;
  min_approvals: number;
  approval_threshold: number;
}

export type { TaskPlan } from "@/store/types/plan";

export interface VisionCapabilities {
  supports_vision: boolean;
  max_image_size_bytes: number;
  supported_formats: string[];
}

/**
 * A part of a multi-modal prompt payload.
 */
export type PromptPart =
  | { type: "text"; text: string }
  | {
      type: "image";
      data: string;
      media_type?: string | null;
      filename?: string | null;
    };

/**
 * A multi-modal prompt payload containing text and/or image parts.
 *
 * This is the format expected by the `send_ai_prompt_with_attachments`
 * command. For text-only prompts, the existing `send_ai_prompt_session`
 * can still be used.
 */
export interface PromptPayload {
  parts: PromptPart[];
}

export type TextPart = Extract<PromptPart, { type: "text" }>;
export type ImagePart = Extract<PromptPart, { type: "image" }>;

